import{useEffect,useState}from"react";import{createEvent,getVendorEvents,getVendorEventRegistrations}from"../../api/eventApi";import{CalendarPlus,Users,Send}from"lucide-react";
const empty={name:"",category:"Workshop",description:"",eventDate:"",startTime:"10:00",endTime:"13:00",venue:"",address:"",city:"Bengaluru",capacity:50,ticketPrice:0,registrationDeadline:"",images:[],terms:""};export default function EventManager(){const[f,setF]=useState(empty),[events,setEvents]=useState([]),[regs,setRegs]=useState([]),[m,setM]=useState("");const load=()=>{getVendorEvents().then(r=>setEvents(r.data?.data||[]));getVendorEventRegistrations().then(r=>setRegs(r.data?.data||[]))};useEffect(() => { load(); }, []);const submit=async()=>{try{await createEvent({...f,capacity:Number(f.capacity),ticketPrice:Number(f.ticketPrice),registrationDeadline:f.registrationDeadline?f.registrationDeadline:null});setM("Event submitted for admin approval");setF(empty);load()}catch(e){setM(e.response?.data?.message||"Could not create event")}};return <div className="page-shell vendor-bg"><p className="eyebrow">EVENTS · V24</p><h1 className="page-title">Event manager</h1>{m&&<div className="mt-4 rounded-xl bg-slate-900 p-3 text-sm text-white">{m}</div>}<div className="mt-7 grid gap-5 xl:grid-cols-3"><div className="card p-5 xl:col-span-2"><h2 className="section-title"><CalendarPlus size={18} className="inline"/> Create event</h2><div className="mt-4 grid gap-3 sm:grid-cols-2">{[["Event name","name"],["Category","category"],["Venue","venue"],["Address","address"],["City","city"]].map(([l,k])=><label className="block" key={k}><span className="label">{l}</span><input className="input" value={f[k]} onChange={e=>setF({...f,[k]:e.target.value})}/></label>)}<label><span className="label">Date</span><input className="input" type="date" value={f.eventDate} onChange={e=>setF({...f,eventDate:e.target.value})}/></label><label><span className="label">Registration deadline</span><input className="input" type="datetime-local" value={f.registrationDeadline} onChange={e=>setF({...f,registrationDeadline:e.target.value})}/></label><label><span className="label">Start</span><input className="input" type="time" value={f.startTime} onChange={e=>setF({...f,startTime:e.target.value})}/></label><label><span className="label">End</span><input className="input" type="time" value={f.endTime} onChange={e=>setF({...f,endTime:e.target.value})}/></label><label><span className="label">Capacity</span><input className="input" type="number" min="1" value={f.capacity} onChange={e=>setF({...f,capacity:e.target.value})}/></label><label><span className="label">Ticket price</span><input className="input" type="number" min="0" value={f.ticketPrice} onChange={e=>setF({...f,ticketPrice:e.target.value})}/></label></div><label className="mt-3 block"><span className="label">Description</span><textarea className="input" value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><button className="btn-primary mt-4" onClick={submit}><Send size={16}/> Submit for approval</button></div><div className="card p-5"><h2 className="section-title">My events</h2><div className="mt-4 space-y-3">{events.map(x=><div className="rounded-xl border p-4" key={x.id}><b>{x.name}</b><p className="mt-1 text-xs text-slate-500">{x.eventDate} · {x.city} · {x.availableSeats}/{x.capacity} seats</p><span className="status-pill mt-2 bg-slate-100 text-slate-600">{x.status}</span></div>)}</div><h2 className="section-title mt-7"><Users size={18} className="inline"/> Registrations</h2><p className="mt-2 text-sm text-slate-500">{regs.length} registration records</p></div></div></div>}
